import {allRecords,getMeta,setMeta,saveRecord,deleteRecord,mergeRecords} from './db.js';
import {makePackage,parsePackage} from './transfer.js';
const $=s=>document.querySelector(s),form=$('#record-form');
let records=[],attachments=[],currentId=crypto.randomUUID(),createdAt=new Date().toISOString(),recorder,stream,recordTimer,draftTimer,queue=Promise.resolve(),urls=[],toastTimer,lastBackup=null;
const text=(tag,value,className)=>{const el=document.createElement(tag);el.textContent=value;if(className)el.className=className;return el;};
function notify(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,6500);}
function fail(error){console.error(error);$('#save-state').textContent='Falha ao salvar';notify(error.name==='QuotaExceededError'?'Armazenamento cheio. Faça backup e libere espaço.':error.message||'Não foi possível concluir.');}
function safe(fn){return (...args)=>Promise.resolve().then(()=>fn(...args)).catch(fail);}
function readForm(){const data=Object.fromEntries(new FormData(form));return {id:currentId,createdAt,updatedAt:new Date().toISOString(),title:data.title.trim(),type:data.type,company:data.company.trim(),person:data.person.trim(),notes:data.notes,tags:data.tags.split(',').map(t=>t.trim()).filter(Boolean),priority:data.priority,nextSteps:data.nextSteps,dimensions:[...document.querySelectorAll('#dimensions input:checked')].map(el=>el.value),followUp:{owner:data.owner,due:data.due,status:data.status},attachments:[...attachments]};}
function hasContent(r){return !!(r.title||r.company||r.person||r.notes.trim()||r.tags.length||r.nextSteps.trim()||r.attachments.length);}
function persistDraft(){clearTimeout(draftTimer);const draft=readForm();$('#save-state').textContent='Salvando…';queue=queue.catch(()=>{}).then(async()=>{await setMeta('draft',hasContent(draft)?draft:null);$('#save-state').textContent='Salvo neste dispositivo';});return queue;}
function scheduleSave(){clearTimeout(draftTimer);$('#save-state').textContent='Salvando…';draftTimer=setTimeout(()=>persistDraft().catch(fail),400);}
function fill(record){form.reset();currentId=record?.id||crypto.randomUUID();createdAt=record?.createdAt||new Date().toISOString();attachments=record?.attachments||[];if(record){for(const key of ['title','type','company','person','notes','priority','nextSteps'])form.elements[key].value=record[key];form.elements.tags.value=record.tags.join(', ');for(const key of ['owner','due','status'])form.elements[key].value=record.followUp?.[key]|| (key==='status'?'Pendente':'');for(const input of document.querySelectorAll('#dimensions input'))input.checked=record.dimensions?.includes(input.value)||false;}$('#editor-title').textContent=records.some(r=>r.id===currentId)?'Editar registro':'Novo registro';$('#save-state').textContent=record?'Recuperado do dispositivo':'Rascunho local';renderAttachments();}
function show(view){for(const el of document.querySelectorAll('.view'))el.hidden=el.id!==view;for(const button of document.querySelectorAll('nav button'))button.classList.toggle('active',button.dataset.view===view);if(view==='library')renderLibrary();if(view==='followups')renderFollowups();}
document.querySelectorAll('nav button').forEach(button=>button.onclick=()=>show(button.dataset.view));
document.querySelectorAll('[data-quick]').forEach(button=>button.onclick=safe(async()=>{if(recorder)throw Error('Pare a gravação antes de abrir outro registro.');if(hasContent(readForm())){await persistDraft();await commit(false);}fill();form.elements.type.value=button.dataset.quick==='voice'?'Insight':button.dataset.quick;show('capture');if(button.dataset.quick==='voice')await startRecording();}));
form.oninput=scheduleSave;form.onchange=scheduleSave;
async function commit(reset=true){if(recorder)throw Error('Pare a gravação antes de salvar.');clearTimeout(draftTimer);await queue.catch(()=>{});const record=readForm();if(!hasContent(record))throw Error('Adicione uma nota, foto ou áudio para salvar.');await saveRecord(record);await refresh();if(reset)fill();notify('Registro salvo no dispositivo.');}
form.onsubmit=safe(async event=>{event.preventDefault();await commit();});
// preventDefault must run synchronously, before the safe promise wrapper.
form.addEventListener('submit',event=>event.preventDefault());
$('#new-record').onclick=safe(async()=>{if(recorder)throw Error('Pare a gravação primeiro.');if(hasContent(readForm())&&!confirm('Descartar o rascunho atual? Registros já salvos serão preservados.'))return;clearTimeout(draftTimer);await queue.catch(()=>{});await setMeta('draft',null);fill();});
function renderAttachments(){urls.forEach(URL.revokeObjectURL);urls=[];const list=$('#attachments-list');list.replaceChildren();for(const attachment of attachments){const item=text('div','','media-item'),url=URL.createObjectURL(attachment.blob);urls.push(url);if(attachment.mime.startsWith('image/')){const img=document.createElement('img');img.src=url;img.alt=attachment.name;item.append(img);}else{const audio=document.createElement('audio');audio.src=url;audio.controls=true;audio.preload='metadata';item.append(audio);}item.append(text('small',`${attachment.name} · ${(attachment.blob.size/1024).toFixed(0)} KB`));const remove=text('button','Remover');remove.type='button';remove.onclick=safe(async()=>{attachments=attachments.filter(a=>a.id!==attachment.id);renderAttachments();await persistDraft();});item.append(remove);list.append(item);}}
for(const id of ['photos','camera','audio-file'])$('#'+id).onchange=safe(async event=>{try{for(const file of event.target.files){const mime=file.type||(id==='audio-file'?'audio/mp4':'image/jpeg');if(!/^(image|audio)\//.test(mime))throw Error('Selecione fotos ou áudios.');if(file.size>100*1024*1024)throw Error('Cada anexo deve ter até 100 MB.');attachments.push({id:crypto.randomUUID(),name:file.name,mime,blob:file});}renderAttachments();await persistDraft();}finally{event.target.value='';}});
async function startRecording(){
  if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Gravação indisponível neste navegador. Importe um áudio de Arquivos.');
  const button=$('#record-audio');button.disabled=true;
  try{stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/mp4','audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus'].find(type=>MediaRecorder.isTypeSupported(type));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);const chunks=[];
    recorder.ondataavailable=event=>{if(event.data.size)chunks.push(event.data);};
    recorder.onstop=safe(async()=>{clearInterval(recordTimer);stream?.getTracks().forEach(track=>track.stop());const type=recorder.mimeType||chunks[0]?.type||'audio/mp4',blob=new Blob(chunks,{type});recorder=null;button.textContent='● Gravar áudio';button.disabled=false;$('#recording-status').textContent='Gravação encerrada.';if(blob.size){attachments.push({id:crypto.randomUUID(),name:`Nota de voz ${new Date().toLocaleTimeString('pt-BR')}`,mime:type,blob});renderAttachments();await persistDraft();}else notify('Nenhum áudio capturado. Tente novamente.');});
    recorder.onerror=()=>{notify('A gravação foi interrompida. Confira o áudio antes de continuar.');if(recorder?.state!=='inactive')recorder.stop();};recorder.start();button.textContent='■ Parar gravação';button.disabled=false;const started=Date.now();recordTimer=setInterval(()=>$('#recording-status').textContent=`Gravando · ${Math.floor((Date.now()-started)/1000)}s · mantenha a tela aberta`,1000);
  }catch(error){stream?.getTracks().forEach(track=>track.stop());button.disabled=false;throw error;}
}
$('#record-audio').onclick=safe(async()=>{if(recorder?.state==='recording'){recorder.stop();$('#record-audio').disabled=true;}else await startRecording();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){persistDraft().catch(fail);if(recorder?.state==='recording'){recorder.stop();notify('Gravação encerrada ao sair do app. Confira o áudio.');}}});
window.addEventListener('beforeunload',event=>{if(recorder?.state==='recording'){event.preventDefault();event.returnValue='';}});
async function refresh(){records=await allRecords();$('#count').textContent=records.length;lastBackup=await getMeta('lastBackup');$('#last-backup').textContent=lastBackup?`Último ZIP gerado: ${new Date(lastBackup.at).toLocaleString('pt-BR')}. Confirme que foi salvo em Arquivos.`:'Nenhum backup nesta instalação.';const pending=records.filter(r=>lastBackup?.versions?.[r.id]!==r.updatedAt).length;$('#backup-state').textContent=pending?`${pending} registro(s) ainda não incluído(s) no último backup.`:records.length?'Todos os registros incluídos no último ZIP gerado.':'Capture seu primeiro registro e faça um backup diário.';renderLibrary();renderFollowups();}
function action(label,fn){const button=text('button',label);button.onclick=safe(fn);return button;}
function recordCard(r){const card=text('article','','card'),top=text('div','','card-top');top.append(text('span',`${r.type} · ${r.priority}`),text('span',new Date(r.createdAt).toLocaleString('pt-BR')));card.append(top,text('h3',r.title||r.company||'Sem título'),text('p',[r.company,r.person].filter(Boolean).join(' · ')));if(r.notes)card.append(text('p',r.notes.length>350?r.notes.slice(0,350)+'…':r.notes));const tags=text('div','','tags');for(const tag of [...(r.dimensions||[]),...r.tags])tags.append(text('span',tag,'tag'));card.append(tags,text('p',`${r.attachments.length} anexo(s) · ${lastBackup?.versions?.[r.id]===r.updatedAt?'Incluído no backup':'Backup pendente'}`));const actions=text('div','','actions');actions.append(action('Abrir / editar',async()=>{if(recorder)throw Error('Pare a gravação primeiro.');if(hasContent(readForm())&&currentId!==r.id){await persistDraft();await commit(false);}fill(r);await persistDraft();show('capture');}),action('Excluir',async()=>{if(!confirm('Excluir este registro? Para recuperá-lo, será necessário um backup anterior.'))return;await deleteRecord(r.id);await refresh();}));card.append(actions);return card;}
function localDate(iso){const d=new Date(iso);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function renderLibrary(){const q=$('#search').value.toLocaleLowerCase('pt-BR'),type=$('#filter-type').value,company=$('#filter-company').value.toLocaleLowerCase('pt-BR'),day=$('#filter-date').value;const result=records.filter(r=>(!type||r.type===type)&&(!day||localDate(r.createdAt)===day)&&r.company.toLocaleLowerCase('pt-BR').includes(company)&&[r.title,r.company,r.person,r.notes,r.nextSteps,...r.tags,...(r.dimensions||[])].join(' ').toLocaleLowerCase('pt-BR').includes(q));$('#records').replaceChildren(...(result.length?result.map(recordCard):[text('p','Nenhum registro encontrado. Capture uma ideia para começar.','empty')]));}
['search','filter-type','filter-company','filter-date'].forEach(id=>$('#'+id).oninput=renderLibrary);
function renderFollowups(){const status=$('#followup-filter').value,result=records.filter(r=>r.nextSteps.trim()&&(!status||r.followUp.status===status));$('#followup-list').replaceChildren(...(result.length?result.map(r=>{const card=recordCard(r);card.append(text('p',r.nextSteps),text('p',`Responsável: ${r.followUp.owner||'—'} · Prazo: ${r.followUp.due||'—'} · ${r.followUp.status}`));card.append(action(r.followUp.status==='Concluído'?'Reabrir pendência':'Marcar concluído',async()=>{await saveRecord({...r,followUp:{...r.followUp,status:r.followUp.status==='Concluído'?'Pendente':'Concluído'},updatedAt:new Date().toISOString()},false);await refresh();}));return card;}):[text('p','Nenhum follow-up neste filtro.','empty')]));}
$('#followup-filter').onchange=renderFollowups;
async function deliver(blob,name){const file=new File([blob],name,{type:'application/zip'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:name});return;}catch(e){if(e.name==='AbortError')throw Error('Compartilhamento cancelado. O backup não foi marcado como concluído.');}}
  const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
}
async function download(mode){if(recorder)throw Error('Pare a gravação antes de exportar.');const button=mode==='backup'?$('#backup-download'):$('#export-download');button.disabled=true;try{await persistDraft();const all=await allRecords(),draft=await getMeta('draft');let selected=all;if(mode==='export'){const from=$('#export-from').value,to=$('#export-to').value;if(from&&to&&from>to)throw Error('O início do período deve ser anterior ao fim.');selected=all.filter(r=>(!from||localDate(r.createdAt)>=from)&&(!to||localDate(r.createdAt)<=to));if(!selected.length)throw Error('Nenhum registro no período selecionado.');}const bytes=selected.reduce((sum,r)=>sum+r.attachments.reduce((n,a)=>n+a.blob.size,0),0)+(mode==='backup'&&draft?draft.attachments.reduce((n,a)=>n+a.blob.size,0):0);if(bytes>450*1024*1024)throw Error('Pacote muito grande. Exporte por períodos menores (até 450 MB de anexos).');const blob=await makePackage(selected,mode==='backup'?draft:null,mode);await deliver(blob,`money2020-${mode}-${new Date().toISOString().slice(0,10)}.zip`);if(mode==='backup')await setMeta('lastBackup',{at:new Date().toISOString(),versions:Object.fromEntries(all.map(r=>[r.id,r.updatedAt]))});await refresh();notify('ZIP gerado. Verifique se foi salvo em Arquivos.');}finally{button.disabled=false;}}
$('#backup-download').onclick=safe(()=>download('backup'));$('#export-download').onclick=safe(()=>download('export'));
$('#restore').onchange=safe(async event=>{try{if(recorder)throw Error('Pare a gravação primeiro.');const file=event.target.files[0];if(!file)return;const imported=await parsePackage(file);if(!confirm(`Restaurar ${imported.records.length} registro(s)? IDs existentes serão atualizados.${imported.draft?' O rascunho do backup substituirá o atual.':''}`))return;clearTimeout(draftTimer);await queue.catch(()=>{});await mergeRecords(imported.records,imported.draft);await refresh();if(imported.draft)fill(imported.draft);notify('Backup validado e restaurado sem duplicar IDs.');}finally{event.target.value='';}});
$('#storage-persist').onclick=safe(async()=>{const granted=await navigator.storage?.persist?.();notify(granted?'Armazenamento persistente autorizado.':'O navegador não garantiu persistência. Continue fazendo backups.');});
function connection(){$('#connection').textContent=navigator.onLine?'Online · dados locais':'Offline · dados locais';}window.addEventListener('online',connection);window.addEventListener('offline',connection);
async function offline(){if(!('serviceWorker' in navigator)){$('#offline-status').textContent='Offline indisponível neste navegador';return;}try{await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;const ready=()=>$('#offline-status').textContent='✓ Aplicativo disponível offline';if(navigator.serviceWorker.controller)ready();else navigator.serviceWorker.addEventListener('controllerchange',ready,{once:true});}catch(e){$('#offline-status').textContent='Falha ao preparar offline. Reabra com internet.';console.error(e);}}
await (async()=>{try{await refresh();fill(await getMeta('draft'));show('home');connection();const estimate=await navigator.storage?.estimate?.();if(estimate)$('#storage-info').textContent=`Uso local: ${((estimate.usage||0)/1024/1024).toFixed(1)} MB. Capacidade estimada: ${((estimate.quota||0)/1024/1024).toFixed(0)} MB.`;await offline();}catch(error){fail(error);$('#offline-status').textContent='Não foi possível iniciar o armazenamento.';}})();
